  examination: string | null;
  diagnosis: string | null;
  icd_codes: string[];
  /** The codes with their titles and WHO URIs */
  icd_terms: IcdTermOut[];
  clinical_note: string | null;
  plan: string | null;
  /** Vital sign code -> value */
  vitals_jsonb: Record<string, unknown>;
